import{_ as e,o as a,c as r,ag as d}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"40-原话金句_INDEX.md - 原话层索引","description":"","frontmatter":{},"headers":[],"relativePath":"40-原话金句/40-原话金句_INDEX.md","filePath":"40-原话金句/40-原话金句_INDEX.md","lastUpdated":1778031108000}'),o={name:"40-原话金句/40-原话金句_INDEX.md"};function l(n,t,h,i,s,u){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="_40-原话金句-index-md-原话层索引" tabindex="-1">40-原话金句_INDEX.md - 原话层索引 <a class="header-anchor" href="#_40-原话金句-index-md-原话层索引" aria-label="Permalink to &quot;40-原话金句_INDEX.md - 原话层索引&quot;">​</a></h1><blockquote><p>本文件索引第四层：金句库。按传统（佛家/道家/儒家/丹道）分类，辅以按模型索引。</p></blockquote><hr><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p><strong>原话金句</strong>保留了空居士精彩原话的口语化、直指人心的感染力。 当前共收录 <strong>~150 条优质金句</strong>，按传统分类和按模型索引两种方式组织。</p><hr><h2 id="按传统分类" tabindex="-1">按传统分类 <a class="header-anchor" href="#按传统分类" aria-label="Permalink to &quot;按传统分类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>传统</th><th>文件</th><th style="text-align:center;">金句数</th><th>来源经典</th></tr></thead><tbody><tr><td><strong>佛家</strong></td><td><a href="/40-原话金句/quote-佛家">quote-佛家</a></td><td style="text-align:center;">~70</td><td>金刚经、心经、六祖坛经、公案、念佛答疑</td></tr><tr><td><strong>道家</strong></td><td><a href="/40-原话金句/quote-道家">quote-道家</a></td><td style="text-align:center;">~25</td><td>道德经讲解</td></tr><tr><td><strong>儒家</strong></td><td><a href="/40-原话金句/quote-儒家">quote-儒家</a></td><td style="text-align:center;">~20</td><td>处世系列、家庭关系、社会伦理</td></tr><tr><td><strong>丹道</strong></td><td><a href="/40-原话金句/quote-丹道">quote-丹道</a></td><td style="text-align:center;">~30</td><td>中论丹道、五篇灵文、练功答疑、站桩</td></tr></tbody></table><h3 id="佛家-70条" tabindex="-1">佛家（~70条） <a class="header-anchor" href="#佛家-70条" aria-label="Permalink to &quot;佛家（~70条）&quot;">​</a></h3><p>涵盖了空居士讲解《金刚经》《心经》《六祖坛经》及公案、念佛问答的精彩原话。</p><p><strong>主题</strong>：心法总纲、对境不住、对法不执、般若智慧、禅宗公案、净土念佛</p><h3 id="道家-25条" tabindex="-1">道家（~25条） <a class="header-anchor" href="#道家-25条" aria-label="Permalink to &quot;道家（~25条）&quot;">​</a></h3><p>涵盖了空居士讲解《道德经》的精彩原话。</p><p><strong>主题</strong>：道与自然、守中、无为、柔弱胜刚强、和光同尘</p><h3 id="儒家-20条" tabindex="-1">儒家（~20条） <a class="header-anchor" href="#儒家-20条" aria-label="Permalink to &quot;儒家（~20条）&quot;">​</a></h3><p>涵盖了空居士关于处世、家庭、社会伦理的精彩原话。</p><p><strong>主题</strong>：家庭道场、待人处世、忍耐智慧、义利之辨、教育子女</p><h3 id="丹道-30条" tabindex="-1">丹道（~30条） <a class="header-anchor" href="#丹道-30条" aria-label="Permalink to &quot;丹道（~30条）&quot;">​</a></h3><p>涵盖了空居士关于丹道修炼、静坐、站桩、功夫层次的精彩原话。</p><p><strong>主题</strong>：顿超法门、神守黄房、似守非守、师力加持、气感与境界、性命双修</p><hr><h2 id="按模型索引" tabindex="-1">按模型索引 <a class="header-anchor" href="#按模型索引" aria-label="Permalink to &quot;按模型索引&quot;">​</a></h2><h3 id="quote-按模型索引" tabindex="-1"><a href="/40-原话金句/quote-按模型索引">quote-按模型索引</a> <a class="header-anchor" href="#quote-按模型索引" aria-label="Permalink to &quot;[quote-按模型索引](/40-原话金句/quote-按模型索引)&quot;">​</a></h3><p><strong>按七大核心模型组织的金句索引</strong></p><table tabindex="0"><thead><tr><th>模型</th><th style="text-align:center;">金句数</th></tr></thead><tbody><tr><td>天人合一</td><td style="text-align:center;">12</td></tr><tr><td>对境不住</td><td style="text-align:center;">14</td></tr><tr><td>对法不执</td><td style="text-align:center;">14</td></tr><tr><td>自然务实</td><td style="text-align:center;">14</td></tr><tr><td>圆融中和</td><td style="text-align:center;">14</td></tr><tr><td>历境炼心</td><td style="text-align:center;">14</td></tr><tr><td>性命双修</td><td style="text-align:center;">16</td></tr></tbody></table><hr><h2 id="金句标准" tabindex="-1">金句标准 <a class="header-anchor" href="#金句标准" aria-label="Permalink to &quot;金句标准&quot;">​</a></h2><p>好的金句应该：</p><ul><li>口语化、有感染力</li><li>直指人心、不绕弯子</li><li>可以独立理解、不依赖上下文</li><li>有行动指导意义</li></ul><h3 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h3><blockquote><p>&quot;静坐时杂念来了，看着它，不跟随，不攀缘，它自然就消失了。&quot;</p></blockquote><blockquote><p>&quot;凡事尽力而为，做人问心无愧。&quot;</p></blockquote><blockquote><p>&quot;司空见惯就是平常心。&quot;</p></blockquote><hr><h2 id="统计" tabindex="-1">统计 <a class="header-anchor" href="#统计" aria-label="Permalink to &quot;统计&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>数量</th></tr></thead><tbody><tr><td>金句总数</td><td>~150 条</td></tr><tr><td>传统分类</td><td>4 个文件（佛家/道家/儒家/丹道）</td></tr><tr><td>模型索引</td><td>7 个模型覆盖</td></tr><tr><td>来源经典</td><td>金刚经、心经、六祖坛经、道德经、中论丹道、五篇灵文、公案、答疑系列、处世系列</td></tr></tbody></table><hr><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><ul><li>2026-05-05：初始化，创建金句框架</li><li>2026-05-06：完成全部金句提炼，~120条</li><li>2026-05-07：<strong>重构为按传统分类</strong>（佛家/道家/儒家/丹道）；从答疑、论坛、处世、丹道原始文章中新增~30条金句；合并原5个文件为4个传统文件；新增儒家金句文件</li></ul>',39)])])}const b=e(o,[["render",l]]);export{q as __pageData,b as default};
